<?php
namespace App\Controllers\Api;
use App\Models\PesanKomunikasiModel;
class WhatsAppController extends BaseApiController
{
 public function send(){ $p=$this->payload();$phone=preg_replace('/[^0-9+]/','',(string)($p['nomor_tujuan']??''));if(str_starts_with($phone,'0'))$phone='62'.substr($phone,1);$message=trim((string)($p['isi_pesan']??''));$classId=(int)($p['kelas_id']??0);if(!$phone||!$message||!$classId)return $this->respond(['ok'=>false,'message'=>'Nomor, pesan, dan kelas wajib diisi.'],422);$u=$this->currentUser();$m=new PesanKomunikasiModel();$id=$m->insert(['kelas_id'=>$classId,'pengirim'=>$u['nama_lengkap']??'AIWalas','penerima'=>$p['nama_penerima']??$phone,'nomor_tujuan'=>$phone,'isi_pesan'=>$message,'kategori'=>'WhatsApp','status_pengiriman'=>'Disiapkan','dibuat_oleh'=>(int)$u['id']],true);$token=env('WHATSAPP_ACCESS_TOKEN');$numberId=env('WHATSAPP_PHONE_NUMBER_ID');$version=env('WHATSAPP_API_VERSION','v20.0');if(!$token||!$numberId){$m->update($id,['status_pengiriman'=>'Gagal']);return $this->respond(['ok'=>false,'message'=>'WhatsApp API belum dikonfigurasi. Isi WHATSAPP_ACCESS_TOKEN dan WHATSAPP_PHONE_NUMBER_ID di .env.','data'=>['id'=>$id]],503);}$ch=curl_init('https://graph.facebook.com/'.$version.'/'.$numberId.'/messages');curl_setopt_array($ch,[CURLOPT_POST=>true,CURLOPT_RETURNTRANSFER=>true,CURLOPT_HTTPHEADER=>['Authorization: Bearer '.$token,'Content-Type: application/json'],CURLOPT_POSTFIELDS=>json_encode(['messaging_product'=>'whatsapp','to'=>$phone,'type'=>'text','text'=>['preview_url'=>false,'body'=>$message]])]);$body=curl_exec($ch);$code=(int)curl_getinfo($ch,CURLINFO_HTTP_CODE);curl_close($ch);$ok=$code>=200&&$code<300;$m->update($id,['status_pengiriman'=>$ok?'Terkirim':'Gagal','dikirim_pada'=>$ok?date('Y-m-d H:i:s'):null]);return $this->respond(['ok'=>$ok,'message'=>$ok?'Pesan WhatsApp terkirim.':'WhatsApp API menolak pesan.','data'=>['id'=>$id,'status'=>$ok?'Terkirim':'Gagal','response'=>json_decode((string)$body,true)]],$ok?200:502); }
}
